begin;
do $esco$
declare
  current_row public.recommendation_catalogues%rowtype;
  mapped jsonb := '[{"careerId":"data-analyst","version":"1.2.1","occupationLabel":"data analyst","occupationUri":"http://data.europa.eu/esco/occupation/d3edb8f8-3a06-47a0-8fb9-9b212c006aa2","rubric":"Faraway practice target: 3/5 (independent routine tasks). Numeric targets and six-area selection are product assumptions, not ESCO ratings or an official top-six ranking.","groups":[{"skill":"SQL","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/9cf681c7-89ec-470c-b651-7fe03786f586","label":"query languages","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/4463a721-69f3-413d-8321-43e3af13a4f1","label":"use databases","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Statistics","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/7ee4c2ea-b349-4bd2-81a3-ec31475d4833","label":"statistics","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/382c11ed-20d5-4ae7-b60e-15fec527fa6c","label":"apply statistical analysis techniques","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Data Visualisation","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/65e58886-bd1e-4c5b-8ca5-8d9b353c8aa1","label":"data visualisation software","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/348b74cd-49ce-4844-8bdf-ec188b497213","label":"visual presentation techniques","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Excel","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/1973c966-f236-40c9-b2d4-5d71a89019be","label":"use spreadsheets software","relation":"optional"}],"note":"Practical app skill selected to represent related source concepts; not an exact ESCO equivalence."},{"skill":"Communication","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/c544a9f3-5945-4b54-afed-de0697852817","label":"report analysis results","relation":"optional"},{"uri":"http://data.europa.eu/esco/skill/c3e36d05-8ae8-447f-bb2b-6f9409f85389","label":"deliver visual presentation of data","relation":"optional"}],"note":"Team-selected grouping of source concepts."},{"skill":"Problem Solving","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/1e77e42a-181f-4b48-8e74-201ce50ffc29","label":"interpret current data","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/54c9c155-9293-4329-8ed2-2e76e8b519d4","label":"define data quality criteria","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/50b100ea-74fd-4706-99db-3e4ca55e51b8","label":"perform data cleansing","relation":"essential"}],"note":"Practical app skill selected to represent related source concepts; not an exact ESCO equivalence."}]},{"careerId":"software-engineer","version":"1.2.1","occupationLabel":"software developer","occupationUri":"http://data.europa.eu/esco/occupation/f2b15a0e-e65a-438a-affb-29b9d50b77d1","rubric":"Faraway practice target: 3/5 (independent routine tasks). Numeric targets and six-area selection are product assumptions, not ESCO ratings or an official top-six ranking.","groups":[{"skill":"JavaScript","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/3cd569a2-4f88-4c1e-9995-8dce8c5e51a7","label":"JavaScript","relation":"optional"},{"uri":"http://data.europa.eu/esco/skill/21d2f96d-35f7-4e3f-9745-c533d2dd6e97","label":"computer programming","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Python","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/ccd0a1d9-afda-43d9-b901-96344886e14d","label":"Python (computer programming)","relation":"optional"}],"note":"Team-selected grouping of source concepts."},{"skill":"Git & DevOps","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/9d2e926f-53d9-41f5-98f3-19dfaa687f3f","label":"tools for software configuration management","relation":"essential"}],"note":"Practical app skill selected to represent related source concepts; not an exact ESCO equivalence."},{"skill":"Project Management","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/7111b95d-0ce3-441a-9d92-4c75d05c4388","label":"project management","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/6a899482-8bcf-40ca-ae67-579a1cc467ab","label":"manage engineering project","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Problem Solving","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/2522a6ce-3202-4ac8-9f5b-b9cb5a3a83a1","label":"debug software","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/f28617ad-afdd-4041-814c-216153a38998","label":"analyse software specifications","relation":"essential"}],"note":"Practical app skill selected to represent related source concepts; not an exact ESCO equivalence."},{"skill":"Prototyping","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/797a4416-0b8d-44f3-8fcd-eb10bd0be6b4","label":"develop software prototype","relation":"essential"}],"note":"Practical app skill selected to represent related source concepts; not an exact ESCO equivalence."}]},{"careerId":"cloud-engineer","version":"1.2.1","occupationLabel":"cloud engineer","occupationUri":"http://data.europa.eu/esco/occupation/349ee6f6-c295-4c38-9b98-48765b55280e","rubric":"Faraway practice target: 3/5 (independent routine tasks). Numeric targets and six-area selection are product assumptions, not ESCO ratings or an official top-six ranking.","groups":[{"skill":"Cloud Computing","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/bd14968e-e409-45af-b362-3495ed7b10e0","label":"cloud technologies","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/11430d93-c835-48ed-8e70-285fa69c9ae6","label":"design cloud architecture","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/6195c5f7-a4fb-425d-a3dd-c4467c4471a3","label":"deploy cloud resource","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Git & DevOps","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/ce8ae6ca-61d8-4174-b457-641de96cbff4","label":"automate cloud tasks","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/09f2f811-a3fb-4de3-a70f-6420a6935575","label":"systems development life-cycle","relation":"essential"}],"note":"Practical app skill selected to represent related source concepts; not an exact ESCO equivalence."},{"skill":"Python","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/ccd0a1d9-afda-43d9-b901-96344886e14d","label":"Python (computer programming)","relation":"optional"}],"note":"Team-selected grouping of source concepts."},{"skill":"Cybersecurity","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/8088750d-8388-4170-a76f-48354c469c44","label":"cyber security","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/c13fb093-5ffb-491a-b8b7-fa2d42a57e2e","label":"implement cloud security and compliance","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"SQL","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/75f839c2-fd9a-4ad3-8921-6e734608568d","label":"use query languages","relation":"optional"},{"uri":"http://data.europa.eu/esco/skill/9ef0f3a0-9ce2-4ef1-a987-0366b5cb2dbe","label":"database development tools","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Problem Solving","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/9e06bac6-6b91-48ca-8b7d-c1f48cdecd7c","label":"solve ICT system problems","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/2522a6ce-3202-4ac8-9f5b-b9cb5a3a83a1","label":"debug software","relation":"essential"}],"note":"Practical app skill selected to represent related source concepts; not an exact ESCO equivalence."}]},{"careerId":"financial-analyst","version":"1.2.1","occupationLabel":"financial analyst","occupationUri":"http://data.europa.eu/esco/occupation/8d586ee9-0ab1-4155-a3b0-2ca786c8e48c","rubric":"Faraway practice target: 3/5 (independent routine tasks). Numeric targets and six-area selection are product assumptions, not ESCO ratings or an official top-six ranking.","groups":[{"skill":"Financial Modelling","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/d37bc902-f640-48d7-9db4-544db9aa65fa","label":"prepare financial projections","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/9c6974e1-8d8b-43e9-b6b0-75da7634bfc9","label":"fundamental analysis","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Accounting","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/ecc18804-a466-40d9-98b4-fba5cd67dd4b","label":"accounting","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/5f1d1319-7954-4a9b-90c7-57668e3a0d4b","label":"interpret financial statements","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Statistics","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/7ee4c2ea-b349-4bd2-81a3-ec31475d4833","label":"statistics","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/6360a934-cc87-4954-9656-b32db20592e3","label":"quantitative analysis","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Communication","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/79c36c91-28a5-44b7-ab9b-7093b2d4b21e","label":"advise on financial matters","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/0f5bd097-ed76-47f7-8f44-93be67967b5f","label":"explain financial jargon","relation":"optional"}],"note":"Team-selected grouping of source concepts."},{"skill":"Risk Management","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/eb8babfb-ab91-4937-a032-6a79f82e9b7f","label":"analyse financial risk","relation":"optional"}],"note":"Team-selected grouping of source concepts."},{"skill":"Excel","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/629685b8-5f9e-4522-8cff-b3e2c4ec625a","label":"digital data processing","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/4b3ae518-6746-4487-8d3b-4cfc063a43d0","label":"use business simulation tools","relation":"essential"}],"note":"Practical app skill selected to represent related source concepts; not an exact ESCO equivalence."}]},{"careerId":"business-analyst","version":"1.2.1","occupationLabel":"ICT business analyst","occupationUri":"http://data.europa.eu/esco/occupation/fe0fa514-b48d-4a53-9757-a283c0baacf0","rubric":"Faraway practice target: 3/5 (independent routine tasks). Numeric targets and six-area selection are product assumptions, not ESCO ratings or an official top-six ranking.","groups":[{"skill":"Stakeholder Management","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/0e0c9c11-b39e-43cf-ba95-2fe646f5de64","label":"identify customer requirements","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/b04f377b-ee80-4b38-aca1-19d266a23b17","label":"analyse business requirements","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Communication","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/a8797f21-1af0-4c5e-98ca-bf1442929363","label":"interact with users to gather requirements","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/385479b7-5da5-4367-9763-0d15b41bb65b","label":"provide user documentation","relation":"optional"}],"note":"Team-selected grouping of source concepts."},{"skill":"Project Management","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/3c76296d-4bbd-44ba-8eaa-95bf275f79b7","label":"manage ICT project","relation":"optional"},{"uri":"http://data.europa.eu/esco/skill/3c03ee71-4a23-448f-b79e-81fd75d27dca","label":"apply change management","relation":"essential"}],"note":"Team-selected grouping of source concepts."},{"skill":"Risk Management","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/4913d0c0-133a-4c46-aac3-f5d4989a982e","label":"product usage risks analysis","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/0daaf096-1639-461c-bf1a-bbeea77e6b67","label":"internal risk management policy","relation":"optional"}],"note":"Team-selected grouping of source concepts."},{"skill":"Prototyping","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/2d6d4784-0992-48e7-b100-22d7229b3f0a","label":"translate requirements into visual design","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/6a7792a9-888a-46ad-afc9-2c0d94c8fde6","label":"create business process models","relation":"essential"}],"note":"Practical app skill selected to represent related source concepts; not an exact ESCO equivalence."},{"skill":"Problem Solving","target":3,"sourceSkills":[{"uri":"http://data.europa.eu/esco/skill/07e51c60-763a-4335-b4ec-70a15f66d328","label":"propose ICT solutions to business problems","relation":"essential"},{"uri":"http://data.europa.eu/esco/skill/56042303-972b-41be-9310-58467599ff7e","label":"analyse business processes","relation":"essential"}],"note":"Practical app skill selected to represent related source concepts; not an exact ESCO equivalence."}]}]'::jsonb;
  item jsonb; axis jsonb; source_skill jsonb; reference jsonb;
  role jsonb; roles jsonb := '[]'::jsonb; needs jsonb; core_skills jsonb;
  new_payload jsonb; target_version text := 'esco-1.2.1-six-areas-v1';
begin
  select * into current_row from public.recommendation_catalogues where is_current for update;
  if not found then raise exception 'Run 002_ai_recommendations.sql first'; end if;
  if current_row.version = target_version then return; end if;
  if exists(select 1 from public.recommendation_catalogues where version=target_version) then
    raise exception 'This version already exists but is not current. Review the current catalogue before reactivating.';
  end if;
  for item in select value from jsonb_array_elements(mapped) loop
    select payload into reference from public.career_skill_references
      where career_id=item->>'careerId' and esco_version='1.2.1';
    if reference is null then raise exception 'Missing ESCO reference for %',item->>'careerId'; end if;
    if not exists(select 1 from jsonb_array_elements(current_row.payload->'careers') c where c->>'id'=item->>'careerId') then
      raise exception 'Career absent from current catalogue: %',item->>'careerId';
    end if;
    for axis in select value from jsonb_array_elements(item->'groups') loop
      for source_skill in select value from jsonb_array_elements(axis->'sourceSkills') loop
        if not exists(select 1 from jsonb_array_elements(reference->'skills') s
          where s->>'uri'=source_skill->>'uri' and s->>'relation'=source_skill->>'relation') then
          raise exception 'Source relationship missing: %',source_skill->>'label';
        end if;
      end loop;
      if not exists(select 1 from jsonb_array_elements(current_row.payload->'courses') c
          where (c->'skills') ? (axis->>'skill')) then
        raise exception 'No catalogue course covers %',axis->>'skill';
      end if;
    end loop;
  end loop;
  for role in select value from jsonb_array_elements(current_row.payload->'careers') loop
    select value into item from jsonb_array_elements(mapped) m where m->>'careerId'=role->>'id';
    if item is not null then
      select jsonb_object_agg(g->>'skill',g->'target'),jsonb_agg(g->'skill') into needs,core_skills from jsonb_array_elements(item->'groups') g;
      role := role || jsonb_build_object('required',needs,'core',core_skills,'skillEvidence',item);
    end if;
    roles := roles || jsonb_build_array(role);
  end loop;
  new_payload := jsonb_set(current_row.payload,'{careers}',roles);
  update public.recommendation_catalogues set is_current=false where version=current_row.version;
  insert into public.recommendation_catalogues(version,published_at,observed_at,status,payload,is_current)
    values(target_version,now(),null,'illustrative',new_payload,true);
end;
$esco$;
commit;

